const NotificationTemplates=lazy(()=>import('@/modules/settings/pages/NotificationTemplates.vue')),NotificationWorkflows=lazy(()=>import('@/modules/settings/pages/NotificationWorkflows.vue'))
const detailComponents={subscription:lazy(()=>import('@/modules/settings/pages/MySubscription.vue')),company:lazy(()=>import('@/modules/settings/pages/CompanySettings.vue')),branches:lazy(()=>import('@/modules/branches/pages/BranchList.vue')),warehouses:lazy(()=>import('@/modules/warehouses/pages/WarehouseList.vue')),units:lazy(()=>import('@/modules/settings/pages/UnitList.vue')),categories:lazy(()=>import('@/modules/settings/pages/CategoryList.vue')),brands:lazy(()=>import('@/modules/settings/pages/BrandList.vue')),cashboxes:lazy(()=>import('@/modules/cashbox/pages/CashBoxList.vue')),payments:lazy(()=>import('@/modules/settings/pages/PaymentMethodList.vue')),invoices:lazy(()=>import('@/modules/settings/pages/InvoiceTypeList.vue'))}
