const titles={uses:'الاستخدامات',company:'بيانات الشركة',locations:'مكان العمل',inventory:'المخزون',billing:'الفواتير والأموال',team:'الفريق',messages:'الرسائل',store:'المتجر',review:'المراجعة'}
const descriptions={uses:'اختر ما تحتاجه الآن. يمكنك إضافة وظائف أخرى وإعادة فتح هذا الدليل في أي وقت.',company:'هذه البيانات تعرّف شركتك للعملاء وتظهر في فواتيرك. نعرض الموجود بدل طلبه من جديد.',locations:'حدد أين تعمل وأين توجد البضاعة. استخدام الفرع والمخزن الموجودين يمنع تكرارهما.',inventory:'اختر الوحدة التي تبيع بها غالبًا. وحدات إضافية والتصنيفات والعلامات يمكن ضبطها أدناه.',billing:'جهز الفواتير والتحصيل والطباعة دون إنشاء حركة مالية.',team:'جهز صلاحيات من سيعملون معك داخل النماذج التالية.',messages:'جهز الوسائل التي اخترتها فقط. التأجيل لا يعطل العمل المستقل عنها.',store:'هذه بيانات شركتك وليست إعدادات إدارة المنصة. حفظها لا ينشر منتجًا أو يفتح البيع تلقائيًا.',review:'راجع النتيجة الفعلية قبل الانتقال إلى عملك اليومي.'}
const features=[{key:'inventory',title:'المنتجات والمخزون',hint:'تسجيل المنتجات والكميات ووحدات البيع'},{key:'sales',title:'المبيعات',hint:'إصدار فواتير البيع واستلام الأموال'},{key:'purchases',title:'المشتريات',hint:'تسجيل مشتريات الموردين'},{key:'team',title:'العمل مع موظفين',hint:'إضافة الفريق وتحديد الصلاحيات'},{key:'email',title:'إرسال البريد الإلكتروني',hint:'إرسال رسائل الشركة'},{key:'whatsapp',title:'إرسال واتساب',hint:'يتطلب حساب إرسال متاحًا لك'},{key:'automation',title:'تنبيهات تلقائية',hint:'مثل تذكير الفواتير في أوقات تختارها'},{key:'store',title:'بيع المنتجات في المتجر',hint:'يمكن تجهيزه الآن أو لاحقًا'}]
const printFormats=[{title:'ورقة عادية A4',value:'standard'},{title:'ورقة صغيرة A5',value:'a5'},{title:'طابعة إيصالات 80 مم',value:'thermal'},{title:'طابعة إيصالات 58 مم',value:'thermal_58'}]
const detailsForStep=computed(()=>({uses:[{title:'اشتراكي وحدود الاستخدام',value:'subscription'}],company:[{title:'الشعار والتواصل والتفضيلات',value:'company'}],locations:[{title:'إدارة الفروع',value:'branches'},{title:'إدارة المخازن',value:'warehouses'}],inventory:[{title:'الوحدات والتحويل بينها',value:'units'},{title:'تصنيفات المنتجات',value:'categories'},{title:'العلامات التجارية',value:'brands'}],billing:[{title:'إدارة الخزائن',value:'cashboxes'},{title:'وسائل الدفع',value:'payments'},{title:'أنواع الفواتير',value:'invoices'}]})[key.value]||[])
const has=feature=>snapshot.value?.data.uses.includes(feature),can=permission=>user.hasPermission(permission)
const taxPercent=computed({get:()=>Number(form.value.rate_bps||0)/100,set:v=>{form.value.rate_bps=Math.round(Number(v||0)*100)}})
function taxChanged(){if(form.value.tax_status!=='registered'){form.value.tax_mode='none';form.value.rate_bps=0;form.value.registration_number=null}}
function fill(){if(!snapshot.value)return;const d=snapshot.value.data,s=d.settings||{};detail.value=null
 if(key.value==='uses')form.value={uses:[...d.uses]}
 else if(key.value==='company')form.value={...d.company,social_links:Array.isArray(d.company.social_links)?JSON.parse(JSON.stringify(d.company.social_links)):[]}
 else if(key.value==='locations'){const b=d.branches.find(b=>b.is_default)||d.branches[0],w=d.warehouses.find(w=>w.is_default)||d.warehouses[0];form.value={branch_id:b?.id,branch_name:b?.name||'الفرع الرئيسي',warehouse_id:w?.id,name:w?.name||'المخزن الرئيسي',location:w?.location||'',latitude:w?.latitude??null,longitude:w?.longitude??null,location_confirmed:!!w?.location_confirmed}}
 else if(key.value==='inventory')form.value={unit_id:s.setup_unit_id||d.units[0]?.id||null,unit_name:'',decimal_places:0,auto_update_purchase_price:!!s.auto_update_purchase_price}
 else if(key.value==='billing')form.value={create_invoice_types:false,invoice_type_ids:d.active_invoice_type_ids.length?[...d.active_invoice_type_ids]:d.invoice_types.filter(t=>d.uses.includes('sales')&&['sale','sales','sales_invoice'].includes(t.code)||d.uses.includes('purchases')&&['purchase','purchases'].includes(t.code)).map(t=>t.id),payment_method_id:s.setup_payment_method_id||d.payment_methods[0]?.id||null,payment_method_name:'',create_cash_box:false,create_cash_customer:false,print_format:s.print_settings?.print_format||'standard',show_logo:s.print_settings?.show_logo??true,footer_text:s.print_settings?.footer_text||''}
 else if(key.value==='store'){const p=d.store?.profile||{},a=p.pickup_address||{},tax=p.tax_profile||{},local=d.store?.delivery?.settings||{},w=d.warehouses.find(w=>w.is_default)||d.warehouses[0];form.value={warehouse_id:p.warehouse_id||w?.id,recipient_name:a.recipient_name||d.company.name,phone:a.phone||d.company.phone,city:a.city||'',governorate_code:a.governorate_code||'',seller_kind:p.business_profile?.seller_kind||null,tax_status:tax.status==='unconfigured'?null:tax.status,tax_mode:tax.mode||'none',rate_bps:tax.rate_bps||0,registration_number:tax.registration_number||null,basis:tax.basis||'',local_enabled:!!local.enabled,radius_km:local.radius_meters?local.radius_meters/1000:null,fee:local.fee_minor/100||0,free_above:local.free_above_minor==null?null:local.free_above_minor/100,payout_type:d.store?.payout_proposal?.type||null,payout_account_holder:d.store?.payout_proposal?.account_holder||'',payout_account_number:d.store?.payout_proposal?.account_number||'',payout_iban:d.store?.payout_proposal?.iban||null}}
 else form.value={}
 baseline.value=JSON.stringify(form.value);nextTick(()=>body.value?.$el?.scrollTo?.({top:0}))
}
function chooseWarehouse(id){const w=snapshot.value.data.warehouses.find(w=>w.id===id);if(w)Object.assign(form.value,{name:w.name,location:w.location,latitude:w.latitude,longitude:w.longitude,location_confirmed:w.location_confirmed})}
function chooseBranch(id){const b=snapshot.value.data.branches.find(b=>b.id===id),w=snapshot.value.data.warehouses.find(w=>w.branch_id===id);form.value.branch_name=b?.name||'';form.value.warehouse_id=w?.id||null;if(w)chooseWarehouse(w.id);else Object.assign(form.value,{name:'المخزن الرئيسي',location:'',latitude:null,longitude:null,location_confirmed:false})}
function selectLogo(image){form.value.logo_id=image.id;form.value.logo_url=image.url;media.value=false}
const dirty=()=>JSON.stringify(form.value)!==baseline.value
function go(step){if(dirty()&&!window.confirm('لديك تعديلات لم تحفظ. هل تريد تركها؟'))return;key.value=step;fill()}
function previous(){go(snapshot.value.steps[index.value-1].key)}
async function next(defer=false){if(await store.save(key.value,current.value.can_edit?form.value:{},defer===true)){key.value=store.snapshot.state.current_step;fill()}}
async function finish(product){if(!await store.save('review',{}))return;if(hideAgain.value!==snapshot.value?.state.hidden&&!await store.setHidden(hideAgain.value))return;store.open=false;await user.fetchUser();if(product)router.push('/app/products/create')}
async function close(){if(store.saving)return;if(dirty()&&!window.confirm('التعديلات الحالية لم تحفظ. المراحل السابقة محفوظة. هل تريد الإغلاق؟'))return;if(hideAgain.value!==snapshot.value?.state.hidden&&!await store.setHidden(hideAgain.value))return;store.open=false}
async function reload(){if(dirty()&&!window.confirm('سيتم تحميل آخر بيانات محفوظة بدل التعديلات الحالية. هل تريد المتابعة؟'))return;await store.load(user.currentUser?.active_company_id);fill()}
watch(()=>store.open,async open=>{if(open){const token=sessionStorage.getItem('token')||localStorage.getItem('token')||'session';if(snapshot.value)sessionStorage.setItem('company_setup_seen_'+user.currentUser?.id+'_'+snapshot.value.company_id,token);hideAgain.value=!!snapshot.value?.state.hidden;key.value=snapshot.value?.state.current_step||'uses';fill();try{const r=await api.get('/store/public/checkout-config');governorates.value=r.data?.data?.governorates||[]}catch{/* retry without losing the current form */}}})
watch(()=>store.snapshot,s=>{if(s&&store.open){if(!s.steps.some(step=>step.key===key.value))key.value=s.state.current_step;fill()}})
watch([()=>user.currentUser?.id,()=>user.currentUser?.active_company_id],async ([userId,id])=>{store.reset();if(!id||!user.currentUser?.is_staff_or_admin)return;store.autoPending=true;await store.load(id);store.autoPending=false},{immediate:true})
let timer
onMounted(()=>{timer=setInterval(()=>{const s=snapshot.value;if(props.blocked||!s||store.open||s.state.hidden||s.state.finished||document.querySelector('.v-overlay--active'))return;const token=sessionStorage.getItem('token')||localStorage.getItem('token')||'session',seenKey='company_setup_seen_'+user.currentUser?.id+'_'+s.company_id;if(sessionStorage.getItem(seenKey)===token)return;sessionStorage.setItem(seenKey,token);store.open=true},1000)})
onUnmounted(()=>clearInterval(timer))
</script>
